import type { FC } from 'react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeftRight, Eraser } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import CompareBox from '@/components/tools/text-compare/CompareBox';
import NavGutter from '@/components/tools/text-compare/NavGutter';
import { usePersistentState } from '@/hooks/usePersistentState';
import { computeDiff } from '@/lib/text-compare/diff';
import type { DiffResult } from '@/lib/text-compare/types';

const buttonBase =
  'inline-flex items-center justify-center gap-1.5 px-3.5 py-2 rounded-lg text-sm font-medium border border-border text-foreground/80 hover:text-foreground hover:border-accent/40 transition-colors disabled:opacity-40 disabled:cursor-not-allowed';

const TextCompare: FC = () => {
  const [original, setOriginal] = usePersistentState<string>('text-compare:original', '');
  const [changed, setChanged] = usePersistentState<string>('text-compare:changed', '');
  const [ignoreCase, setIgnoreCase] = usePersistentState<boolean>('text-compare:ignore-case', false);
  const [ignoreWhitespace, setIgnoreWhitespace] = usePersistentState<boolean>('text-compare:ignore-whitespace', false);

  // Comparison only ever runs when "Compare" is clicked — result === null
  // means both boxes are plain editable textareas; a result switches them to
  // the read-only highlighted view.
  const [result, setResult] = useState<DiffResult | null>(null);
  const [activeChangeIndex, setActiveChangeIndex] = useState(-1);

  const leftRowRefs = useRef<(HTMLDivElement | null)[]>([]);
  const leftContainerRef = useRef<HTMLDivElement | null>(null);
  const rightContainerRef = useRef<HTMLDivElement | null>(null);
  const isSyncingScroll = useRef(false);

  const registerLeftRowRef = useCallback((rowIndex: number, el: HTMLDivElement | null) => {
    leftRowRefs.current[rowIndex] = el;
  }, []);

  // changeAnchors[c] = index of the first row belonging to change c — used to
  // find something to scroll to when jumping to change c.
  const changeAnchors = useMemo(() => {
    const anchors: number[] = [];
    result?.rows.forEach((row, i) => {
      if (row.changeIndex !== null && anchors[row.changeIndex] === undefined) anchors[row.changeIndex] = i;
    });
    return anchors;
  }, [result]);

  const goToChange = useCallback(
    (index: number) => {
      if (!result || result.changeCount === 0) return;
      const wrapped = ((index % result.changeCount) + result.changeCount) % result.changeCount;
      setActiveChangeIndex(wrapped);

      const el = leftRowRefs.current[changeAnchors[wrapped]];
      const container = leftContainerRef.current;
      if (!el || !container) return;
      const target = Math.max(0, el.offsetTop - container.clientHeight / 2 + el.clientHeight / 2);
      container.scrollTo({ top: target, behavior: 'smooth' });
      rightContainerRef.current?.scrollTo({ top: target, behavior: 'smooth' });
    },
    [result, changeAnchors],
  );

  // A fresh comparison should land you on the first change, not the top of
  // a wall of unchanged context.
  useEffect(() => {
    if (result && result.changeCount > 0) goToChange(0);
    else setActiveChangeIndex(-1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [result]);

  const runCompare = (orig: string, chg: string) => {
    setResult(computeDiff(orig, chg, { ignoreCase, ignoreWhitespace }));
  };

  const handleCompare = () => runCompare(original, changed);

  const handleSwap = () => {
    const nextOriginal = changed;
    const nextChanged = original;
    setOriginal(nextOriginal);
    setChanged(nextChanged);
    if (result) runCompare(nextOriginal, nextChanged);
  };

  const handleClear = () => {
    setOriginal('');
    setChanged('');
    setResult(null);
  };

  const handleRequestEdit = () => setResult(null);

  // Linked scrolling: dragging either scrollbar (not just the nav arrows)
  // keeps both panes lined up, the way a side-by-side diff viewer should.
  const handleLeftScroll = () => {
    if (isSyncingScroll.current) {
      isSyncingScroll.current = false;
      return;
    }
    if (!leftContainerRef.current || !rightContainerRef.current) return;
    isSyncingScroll.current = true;
    rightContainerRef.current.scrollTop = leftContainerRef.current.scrollTop;
  };

  const handleRightScroll = () => {
    if (isSyncingScroll.current) {
      isSyncingScroll.current = false;
      return;
    }
    if (!leftContainerRef.current || !rightContainerRef.current) return;
    isSyncingScroll.current = true;
    leftContainerRef.current.scrollTop = rightContainerRef.current.scrollTop;
  };

  const leftCells = result ? result.rows.map((row) => row.left) : null;
  const rightCells = result ? result.rows.map((row) => row.right) : null;
  const changeIndexes = result ? result.rows.map((row) => row.changeIndex) : [];

  return (
    <ToolLayout
      title="Text Compare"
      description="Paste two texts or drop in files, then click Compare — every change is highlighted right inside the boxes."
    >
      <div className="flex flex-col h-[75vh] min-h-[520px] gap-4">
        <div className="flex flex-wrap items-center justify-between gap-3 shrink-0">
          <div className="flex items-center gap-2">
            <button type="button" onClick={handleClear} disabled={!original && !changed} className={buttonBase}>
              <Eraser className="w-3.5 h-3.5" />
              Clear
            </button>
            <button type="button" onClick={handleSwap} className={buttonBase}>
              <ArrowLeftRight className="w-3.5 h-3.5" />
              Swap
            </button>
          </div>

          <div className="flex flex-wrap items-center gap-4">
            <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={ignoreCase}
                onChange={(e) => setIgnoreCase(e.target.checked)}
                className="w-4 h-4 rounded border-input accent-accent"
              />
              Ignore case
            </label>
            <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={ignoreWhitespace}
                onChange={(e) => setIgnoreWhitespace(e.target.checked)}
                className="w-4 h-4 rounded border-input accent-accent"
              />
              Ignore whitespace
            </label>
            <button
              type="button"
              onClick={handleCompare}
              disabled={!original && !changed}
              className="inline-flex items-center justify-center px-5 py-2 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              Compare
            </button>
          </div>
        </div>

        <div className="flex flex-col md:flex-row flex-1 min-h-0 gap-0">
          <CompareBox
            label="Original"
            value={original}
            onChange={setOriginal}
            cells={leftCells}
            changeIndexes={changeIndexes}
            activeChangeIndex={activeChangeIndex}
            registerRowRef={registerLeftRowRef}
            onRequestEdit={handleRequestEdit}
            onScroll={handleLeftScroll}
            scrollRef={(el) => {
              leftContainerRef.current = el;
            }}
          />

          <NavGutter changeCount={result?.changeCount ?? 0} activeIndex={activeChangeIndex} onPrev={() => goToChange(activeChangeIndex - 1)} onNext={() => goToChange(activeChangeIndex + 1)} />

          <CompareBox
            label="Changed"
            value={changed}
            onChange={setChanged}
            cells={rightCells}
            changeIndexes={changeIndexes}
            activeChangeIndex={activeChangeIndex}
            onRequestEdit={handleRequestEdit}
            onScroll={handleRightScroll}
            scrollRef={(el) => {
              rightContainerRef.current = el;
            }}
          />
        </div>
      </div>
    </ToolLayout>
  );
};

export default TextCompare;
