import { diffLines, diffWordsWithSpace, type Change } from 'diff';
import type { DiffCell, DiffOptions, DiffResult, DiffRow, DiffSubSegment } from './types';

// jsdiff's diffLines type declarations don't list `ignoreCase` (only
// diffChars/diffWords do), but the underlying comparator honours it
// regardless of which tokenizer is used — see node_modules/diff's
// Diff.equals(). Narrow cast, contained to this one call.
function diffLinesCaseInsensitive(oldStr: string, newStr: string, ignoreWhitespace: boolean, ignoreCase: boolean): Change[] {
  return diffLines(oldStr, newStr, { ignoreWhitespace, ignoreCase } as Parameters<typeof diffLines>[2]);
}

// jsdiff keeps each line's trailing "\n" attached to `value`. Split into bare
// lines without producing a bogus trailing empty entry.
function splitLines(value: string): string[] {
  const lines = value.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  return lines;
}

// Word-level sub-highlighting for a one-line-replaced-by-one-line hunk, so
// e.g. "jumps" -> "leaps" highlights just that word instead of the whole
// line. Deliberately only used for a single old line vs a single new line:
// running a word diff across a *joined, multi-line* block lets repeated
// words (very common — "the", "line", ...) on unrelated lines cross-match
// each other, producing highlights that don't correspond to what actually
// changed. Hunks spanning more than one line per side fall back to
// colouring whole lines instead.
function wordDiffSingleLine(
  oldLine: string,
  newLine: string,
  ignoreCase: boolean,
): { oldSub: DiffSubSegment[]; newSub: DiffSubSegment[] } {
  const parts = diffWordsWithSpace(oldLine, newLine, { ignoreCase });
  const oldSub: DiffSubSegment[] = [];
  const newSub: DiffSubSegment[] = [];

  for (const part of parts) {
    if (!part.added) oldSub.push({ text: part.value, changed: !!part.removed });
    if (!part.removed) newSub.push({ text: part.value, changed: !!part.added });
  }

  return { oldSub, newSub };
}

const BLANK_CELL: DiffCell = { kind: 'blank', text: '' };

// Builds a row-aligned (side-by-side) line diff: both `left` and `right`
// always have the same number of rows, in the same order, so the two panes
// can be rendered and scrolled in lockstep — a pure insertion pads the left
// side with a blank row, a pure deletion pads the right side, and so on.
export function computeDiff(oldText: string, newText: string, options: DiffOptions): DiffResult {
  const parts = diffLinesCaseInsensitive(oldText, newText, options.ignoreWhitespace, options.ignoreCase);
  const rows: DiffRow[] = [];
  let changeIndex = 0;
  let addedCount = 0;
  let removedCount = 0;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    if (!part.added && !part.removed) {
      for (const line of splitLines(part.value)) {
        rows.push({ left: { kind: 'context', text: line }, right: { kind: 'context', text: line }, changeIndex: null });
      }
      continue;
    }

    if (part.removed) {
      const next = parts[i + 1];
      const removedLines = splitLines(part.value);
      const idx = changeIndex++;
      removedCount += removedLines.length;

      if (next?.added) {
        // A "replace" hunk — pair it with the following added block.
        const addedLines = splitLines(next.value);
        addedCount += addedLines.length;

        if (removedLines.length === 1 && addedLines.length === 1) {
          const { oldSub, newSub } = wordDiffSingleLine(removedLines[0], addedLines[0], options.ignoreCase);
          rows.push({
            left: { kind: 'removed', text: removedLines[0], subSegments: oldSub },
            right: { kind: 'added', text: addedLines[0], subSegments: newSub },
            changeIndex: idx,
          });
        } else {
          const rowCount = Math.max(removedLines.length, addedLines.length);
          for (let li = 0; li < rowCount; li++) {
            rows.push({
              left: li < removedLines.length ? { kind: 'removed', text: removedLines[li] } : BLANK_CELL,
              right: li < addedLines.length ? { kind: 'added', text: addedLines[li] } : BLANK_CELL,
              changeIndex: idx,
            });
          }
        }
        i++; // consumed the paired added part
        continue;
      }

      for (const line of removedLines) {
        rows.push({ left: { kind: 'removed', text: line }, right: BLANK_CELL, changeIndex: idx });
      }
      continue;
    }

    // Standalone addition (no preceding removal — that case is consumed above).
    const addedLines = splitLines(part.value);
    const idx = changeIndex++;
    addedCount += addedLines.length;
    for (const line of addedLines) {
      rows.push({ left: BLANK_CELL, right: { kind: 'added', text: line }, changeIndex: idx });
    }
  }

  return {
    identical: changeIndex === 0,
    changeCount: changeIndex,
    addedCount,
    removedCount,
    rows,
  };
}
