import type { FC } from 'react';
import { useRef } from 'react';
import { toast } from 'sonner';
import { UploadCloud, Pencil } from 'lucide-react';
import type { CellKind, DiffCell } from '@/lib/text-compare/types';

interface CompareBoxProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  // Present only once a comparison has been run — switches the box from an
  // editable textarea to a read-only highlighted view of these cells.
  cells: DiffCell[] | null;
  changeIndexes: (number | null)[];
  activeChangeIndex: number;
  registerRowRef?: (rowIndex: number, el: HTMLDivElement | null) => void;
  onRequestEdit: () => void;
  onScroll?: () => void;
  scrollRef: (el: HTMLDivElement | null) => void;
}

function rowClasses(kind: CellKind, isActive: boolean): string {
  const tone = kind === 'removed' ? 'bg-red-500/10' : kind === 'added' ? 'bg-emerald-500/10' : kind === 'blank' ? 'bg-muted/10' : '';
  const active = isActive ? 'ring-1 ring-inset ring-accent/60' : '';
  return `px-3 whitespace-pre-wrap break-words leading-relaxed ${tone} ${active}`.trim();
}

const CellContent: FC<{ cell: DiffCell }> = ({ cell }) => {
  if (cell.kind === 'blank') return <>{' '}</>;
  if (!cell.subSegments) {
    return <span className={cell.kind === 'context' ? 'text-foreground/75' : 'text-foreground'}>{cell.text || ' '}</span>;
  }
  return (
    <span>
      {cell.subSegments.map((segment, i) =>
        segment.changed ? (
          <mark
            key={i}
            className={`rounded-sm px-0.5 ${
              cell.kind === 'removed' ? 'bg-red-500/30 text-red-100' : 'bg-emerald-500/30 text-emerald-100'
            }`}
          >
            {segment.text}
          </mark>
        ) : (
          <span key={i} className="text-foreground/75">
            {segment.text}
          </span>
        ),
      )}
    </span>
  );
};

const CompareBox: FC<CompareBoxProps> = ({
  label,
  value,
  onChange,
  cells,
  changeIndexes,
  activeChangeIndex,
  registerRowRef,
  onRequestEdit,
  onScroll,
  scrollRef,
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const loadFile = async (file: File) => {
    try {
      onChange(await file.text());
    } catch {
      toast.error("Couldn't read that file as text");
    }
  };

  return (
    <div className="glass-panel hover:border-border flex flex-col flex-1 min-w-0 overflow-hidden">
      <div className="flex items-center justify-between px-3 py-2 border-b border-border shrink-0">
        <span className="text-sm font-medium text-foreground">{label}</span>
        <div className="flex items-center gap-1">
          {cells !== null && (
            <button
              type="button"
              onClick={onRequestEdit}
              aria-label={`Edit ${label}`}
              title="Edit"
              className="p-1.5 rounded-md text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
            >
              <Pencil className="w-4 h-4" />
            </button>
          )}
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            aria-label={`Upload a file for ${label}`}
            title="Upload a file"
            className="p-1.5 rounded-md text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
          >
            <UploadCloud className="w-4 h-4" />
          </button>
        </div>
        <input
          ref={inputRef}
          type="file"
          accept=".txt,.md,.markdown,.json,.csv,.log,.xml,.html,.htm,.css,.js,.jsx,.ts,.tsx,.yml,.yaml,text/*"
          className="hidden"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) loadFile(file);
            e.target.value = '';
          }}
        />
      </div>

      {cells === null ? (
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Paste text here, or drop a file..."
          spellCheck={false}
          className="flex-1 w-full resize-none bg-background/50 px-3 py-2.5 font-mono text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none"
        />
      ) : (
        <div
          ref={scrollRef}
          onScroll={onScroll}
          className="flex-1 overflow-y-auto font-mono text-sm py-1 select-text"
        >
          {cells.map((cell, i) => (
            <div
              key={i}
              ref={(el) => registerRowRef?.(i, el)}
              className={rowClasses(cell.kind, changeIndexes[i] !== null && changeIndexes[i] === activeChangeIndex)}
            >
              <CellContent cell={cell} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CompareBox;
