import type { FC } from 'react';
import { ChevronUp, ChevronDown, ChevronLeft, ChevronRight, CheckCircle2 } from 'lucide-react';

interface NavGutterProps {
  changeCount: number;
  activeIndex: number;
  onPrev: () => void;
  onNext: () => void;
}

const navButton =
  'p-1.5 rounded-full border border-border text-foreground/80 hover:text-accent hover:border-accent/40 transition-colors disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:border-border disabled:hover:text-foreground/80';

// Sits between the two compare boxes so "next/previous change" is reachable
// without scrolling back to a toolbar — see TextCompare. Both boxes scroll
// in lockstep (row-aligned diff), so jumping here moves both panes together.
const NavGutter: FC<NavGutterProps> = ({ changeCount, activeIndex, onPrev, onNext }) => (
  <div className="flex md:flex-col items-center justify-center gap-2 py-2 md:py-0 md:px-1 shrink-0">
    <div className="flex md:flex-col items-center gap-2 md:sticky md:top-1/2 md:-translate-y-1/2">
      {changeCount === 0 ? (
        <CheckCircle2 className="w-5 h-5 text-emerald-500" aria-label="No differences" />
      ) : (
        <>
          <button type="button" onClick={onPrev} aria-label="Previous change" title="Previous change" className={navButton}>
            <ChevronLeft className="w-4 h-4 md:hidden" />
            <ChevronUp className="w-4 h-4 hidden md:block" />
          </button>
          <span className="text-xs font-medium text-muted-foreground whitespace-nowrap tabular-nums">
            {activeIndex + 1}/{changeCount}
          </span>
          <button type="button" onClick={onNext} aria-label="Next change" title="Next change" className={navButton}>
            <ChevronRight className="w-4 h-4 md:hidden" />
            <ChevronDown className="w-4 h-4 hidden md:block" />
          </button>
        </>
      )}
    </div>
  </div>
);

export default NavGutter;
